-- Camp Yalla admission agreement: signed online at checkout, per child, before paying for camp
-- days. It covers the camp days in that purchase (frequency per_booking), so families sign again on
-- each later camp purchase. Initials on Sections 3, 10 and 11, a checkbox and a drawn signature.
-- Required for every Camp Yalla booking. Safe to re-run.
INSERT INTO "form_templates" ("id", "title", "kind", "description", "per_child", "requires_signature", "frequency", "valid_for_months", "enforcement", "status")
VALUES ('camp-agreement', 'Camp Yalla Admission Agreement', 'policy', 'Signed at checkout for the camp days in each purchase.', true, true, 'per_booking', NULL, 'blocks_booking', 'active')
ON CONFLICT ("id") DO NOTHING;
--> statement-breakpoint
INSERT INTO "form_versions" ("id", "template_id", "version", "body", "fields", "content_hash", "requires_resign", "published_by")
VALUES ('camp-agreement-v1', 'camp-agreement', 1, 'Please read this agreement carefully. Add your initials where asked, then sign at the end. Your signature covers the camp days in this purchase.', '[{"id":"intro","type":"info","text":"**Camp Yalla Admission Agreement · 2026–2027**\n\nThis agreement is between Yalla Childcare LLC, doing business as Yalla Coworking & Childcare (“Yalla”), and the parent or caregiver signing below (the “Parent/Caregiver”), for the child named on this agreement (the “Child”). It covers the Camp Yalla day or days booked for the Child in the purchase during which it is signed. A new agreement is signed at checkout for each later purchase of camp days.\n\nThis agreement is a binding contract enforceable under the laws of the State of California. By signing, the Parent/Caregiver confirms they have read and accept these terms."},{"id":"s1","type":"heading","text":"1. Overview"},{"id":"s1-body","type":"info","text":"Camp Yalla is operated by Yalla Coworking & Childcare at **408 Nutmeg Street, San Diego, CA 92103**. Camp Yalla operates as a license-exempt instructional program (see Section 10). Camp is directed and managed by a team of qualified administrators and caregivers committed to safe, joyful, hands-on days for children.\n\nThis agreement applies to **Camp Yalla**: individual camp days for children 18 months to 10 years. Each camp is built around an idea children can explore with their hands: making, building, growing, getting messy and discovering. In this agreement, “camp” means non-medical supervision and enrichment experiences provided while the Child is on site."},{"id":"s2","type":"heading","text":"2. Camp days, hours and booking"},{"id":"s2-body","type":"info","text":"Camp Yalla runs **9:00 AM – 3:00 PM**. By signing this agreement at checkout, the Parent/Caregiver is booking camp for the Child on the camp day or days selected in this purchase, as shown in the booking summary.\n\nOn each camp day, the Child will be in their age group, assigned automatically from the Child’s date of birth, with the following guide-to-child ratio:\n\n- **18 months – 3 years:** one guide for every six children (1:6)\n- **4 – 7 years:** one guide for every eight children (1:8)\n- **8 – 10 years:** one guide for every eight children (1:8)\n\nAt Yalla, we use the word **guide** for the highly qualified team members who oversee the campers on camp days.\n\nCamp days are booked online through the Yalla website or the Family Portal, one day at a time or several at once. A place is available only when there is an opening in the Child’s age group. Booking for a camp day stays open until every place in the age group is sold or until 30 minutes before camp begins, whichever comes first.\n\nTwo optional extras can be added per child, per day, at booking:\n\n- **Early Bird:** 8:00 – 9:00 AM, $20\n- **Late stay:** 3:00 – 4:30 PM, $30"},{"id":"s3","type":"heading","text":"3. Rates, reservations and payment"},{"id":"s3-body","type":"info","text":"- **Camp day (9:00 AM – 3:00 PM):** $160 per child\n- **Early Bird (8:00 – 9:00 AM):** $20 per child\n- **Late stay (3:00 – 4:30 PM):** $30 per child\n\nCamp rates include a morning snack, a light afternoon snack, materials and participation in all camp programming during the Child’s booked hours. When siblings attend camp on the same day, each additional child receives a 10% sibling discount, applied automatically at checkout.\n\nAll camp days must be booked in advance and are paid in full at the time of booking. A place is reserved for the Child once payment is complete. Dates that have not been booked and paid for are not held, and availability may change. Booking a camp day does not secure or prioritize a place on any future camp day."},{"id":"init-rates","type":"initials","label":"I have read and agree to Section 3: Camp rates, reservations and payment.","required":true},{"id":"s4","type":"heading","text":"4. Cancellations, absences and credits"},{"id":"s4-body","type":"info","text":"When the Parent/Caregiver cancels a camp day at least 24 hours before it begins, the amount paid is returned to the family’s Yalla Wallet as a credit. Credits can be used toward future Yalla bookings for up to 24 months from the date they are issued, have no cash value and are not refunded or transferred, except where required by law. Cancellations made less than 24 hours before camp begins, and no-shows, are not eligible for credit.\n\nIllness and other extenuating circumstances may be exempt from the 24-hour requirement; please contact Yalla as soon as possible. Cancel through the Family Portal, call 619.775.4008 or email hello@yallaspacesd.com.\n\nIf Yalla cancels or significantly changes a camp day, the Parent/Caregiver may choose either a Yalla Wallet credit for the full amount plus 5%, or a full refund to the original payment method."},{"id":"s5","type":"heading","text":"5. Child illness policy"},{"id":"s5-body","type":"info","text":"The Parent/Caregiver agrees to follow Yalla’s [Illness Policy](/portal/illness-policy), available in the Family Portal. If the Child shows signs or symptoms of illness described in the policy, the Child will be separated from the group and supervised by Yalla staff until the Parent/Caregiver or another authorized adult collects the Child.\n\nThe Child will also be sent home when Yalla believes, in its sole judgment, that the Child’s condition poses a threat to the health or safety of the Child, other children or staff. Because the Parent/Caregiver is not required to stay on site during camp, **the Parent/Caregiver must keep their phone on, stay reachable throughout the camp day, and collect the Child within sixty (60) minutes of being notified of the Child’s illness.** After sixty minutes, the Parent/Caregiver will be charged the actual cost of any additional expenses related to isolated care.\n\nIf the Child is sent home because of illness, the rest of that camp day is treated as an absence under Section 4.\n\nThe Child should be symptom-free for 24 hours before returning to camp. Knowingly bringing a sick child to Yalla is a serious matter; repeated instances may result in the permanent end of camp booking as described in Section 6."},{"id":"s6","type":"heading","text":"6. Ending camp participation"},{"id":"s6-body","type":"info","text":"Yalla may end the Child’s participation in Camp Yalla **effective immediately** if any of the following occur:\n\n- In the sole discretion of Yalla’s leadership team, the behavior of the Child or the Parent/Caregiver presents a significant risk to the physical or emotional well-being of Yalla staff or anyone else on the premises, and that risk cannot be reasonably resolved through restorative communication.\n- Any amount owed to Yalla (for example, a late departure fee) is not paid within 10 days after it is due.\n- The Child is collected late more than three times in any thirty-day period without advance notice to Yalla.\n\n**Yalla also reserves the right to suspend or permanently end camp booking at any time for any of the following reasons:**\n\n- Repeated failure to follow Yalla’s policies\n- Non-payment or repeated late payment of amounts owed\n- Behavior deemed unsafe or harmful by Yalla’s leadership\n- Repeated late departures\n- Missing required documentation\n\nThese decisions are made at Yalla’s sole discretion to preserve the safety and integrity of the program."},{"id":"s7","type":"heading","text":"7. Availability"},{"id":"s7-body","type":"info","text":"Camp days can be booked at any time during the year; however, availability is not guaranteed. Each age group has a limited number of places, and a camp day is available only when there is an opening in the Child’s age group. Signing this agreement does not guarantee a place on any particular day."},{"id":"s8","type":"heading","text":"8. Arrival, departure and releasing children"},{"id":"s8-body","type":"info","text":"Yalla will release the Child only to:\n\n- The Parent/Caregiver\n- An adult the Parent/Caregiver has authorized in writing in advance, listed in the family’s profile; or\n- Police or child welfare workers with proper authorization.\n\n**Yalla will never release the Child to anyone under the age of 18.**\n\nThe Parent/Caregiver or an authorized adult must check the Child in and sign the Child out at Yalla’s lobby kiosk at arrival and departure **every camp day**. Camp arrival is at 9:00 AM, or 8:00 AM with Early Bird. Anyone other than the Parent/Caregiver who collects the Child must show a driver’s license or other valid photo identification.\n\nPlease plan to collect the Child by the end of the booked day: 3:00 PM, or 4:30 PM with the late stay. After a five-minute grace period, a late departure fee of $10 is charged for each additional ten minutes, or portion of ten minutes."},{"id":"s9","type":"heading","text":"9. Guides and substitute care"},{"id":"s9-body","type":"info","text":"Each camp age group has its own guides, who set the rhythm of the day and introduce themselves at arrival. All caregivers are CPR and First Aid certified and have completed a LiveScan background check. When a guide is absent, a qualified substitute who knows Yalla’s children and routines steps in, so camp does not have to close.\n\nThe guide-to-child ratios in Section 2 are maintained throughout each camp day."},{"id":"s10","type":"heading","text":"10. Legal status and parent availability"},{"id":"s10-body","type":"info","text":"Camp Yalla operates as a license-exempt instructional program pursuant to California Health and Safety Code §1596.792(l). Camp provides developmentally appropriate camp programming exclusively during regularly scheduled school vacations in the San Diego Unified School District, where the program is located. Camp serves children ages 18 months through 10 years and operates within the applicable statutory limit of 15 days for camp sessions added together.\n\nThe Parent/Caregiver acknowledges that Camp Yalla is exempt from California child day care licensing requirements and is not a licensed child day care program. Parents/Caregivers are not required to remain on the premises during their child’s scheduled camp session, but agree to keep their phone on and remain reachable throughout the Child’s booked hours. Camp Yalla’s license-exempt status does not relieve it of obligations imposed by other applicable laws."},{"id":"init-legal","type":"initials","label":"I have read and agree to Section 10, including that Camp Yalla is a license-exempt program and that I will remain reachable by phone for the whole of every camp day.","required":true},{"id":"s11","type":"heading","text":"11. Family Handbook"},{"id":"s11-body","type":"info","text":"On behalf of themselves and the Child, the Parent/Caregiver agrees to follow Yalla’s policies, rules and regulations, as Yalla may update them, including those in the [Yalla Family Handbook](/portal/handbook), available in the Family Portal. By entering into this agreement, the Parent/Caregiver agrees to accept and abide by Yalla’s philosophy, rules, regulations, policies, procedures and standards expressed or implied in the Family Handbook or other written Yalla policies."},{"id":"init-handbook","type":"initials","label":"I have read and agree to Section 11: Yalla’s Family Handbook and policies.","required":true},{"id":"s12","type":"heading","text":"12. Parental consent and indemnity"},{"id":"s12-body","type":"info","text":"The Parent/Caregiver gives permission for the Child to take part in all Camp Yalla programming, including hands-on activities such as making, building, growing, messy play and supervised water play, and daily caregiving. Camp takes place entirely on Yalla’s premises; there are no outings. The Parent/Caregiver shall indemnify, defend, release and hold harmless Yalla from and against any and all claims, damages, expenses and other liabilities or injuries arising out of the Child’s participation in camp activities, excluding only liabilities or injuries caused by the sole gross negligence of Yalla."},{"id":"s13","type":"heading","text":"13. Force majeure"},{"id":"s13-body","type":"info","text":"Yalla’s failure to perform under this agreement is excused to the extent it is caused, in whole or in part, by events beyond Yalla’s control, including without limitation acts of God, disease, epidemic, pandemic, quarantine, governmental actions, terrorism or threats of terrorism, fire, flood, earthquake, storm, explosion, lightning, power surges or failures, the elements, civil disturbances, strikes or labor disputes, failures of transportation facilities, or any similar unforeseen event that makes performance commercially impracticable, illegal or impossible (a “Force Majeure Event”).\n\nThe parties agree that if a Force Majeure Event occurs, Yalla is relieved from performance under this agreement whether or not the event was foreseeable when this agreement was signed. Within a reasonable time after a Force Majeure Event first occurs, Yalla will notify the Parent/Caregiver by email or other written correspondence. Yalla may suspend camp and related activities, or take other measures in response, with as little as one hour’s notice, as Yalla considers necessary."},{"id":"s14","type":"heading","text":"14. Duty to report child abuse"},{"id":"s14-body","type":"info","text":"Yalla staff are mandated reporters of suspected child abuse under California Penal Code §11166. Staff who, in their professional capacity or within the scope of their employment, know of or observe a child whom they know or reasonably suspect has been the victim of child abuse have a legal duty to report it to a child protective agency. Staff who know of or reasonably suspect that mental suffering has been inflicted on a child, or that a child’s emotional well-being is endangered in any other way, must also report it to a child protective agency."},{"id":"s15","type":"heading","text":"15. Food, belongings and personal care"},{"id":"s15-body","type":"info","text":"The Parent/Caregiver provides the Child’s lunch each camp day, following the guidelines in the [Yalla Family Handbook](/portal/handbook).\n\n- The Child must bring a nutritious, ready-to-eat packed lunch and a labeled water bottle each camp day, following Yalla’s dietary restrictions, choking-prevention requirements and safe food preparation policies. Food must be fully prepared in advance, stored with ice packs or in a thermos, and cut into safe, age-appropriate portions.\n- Yalla provides a morning snack and a light afternoon snack.\n\nIf the Child arrives without enough food, or with food that does not follow Yalla’s safety or allergy guidelines, Yalla may ask the Parent/Caregiver to provide appropriate food. If food is missing or unsuitable and it is not resolved promptly, the Child may be sent home for the day. Yalla is a nut-free environment.\n\n**What to bring.** The Parent/Caregiver sends the Child each camp day with, labeled with the Child’s name:\n\n- A packed lunch and a water bottle\n- Sunscreen and a sunhat\n- A light jacket\n- A change of clothes\n\n**Rest time (18 months – 3 years).** Children in the youngest group have a rest time each camp day. The Parent/Caregiver provides a sheet and a light blanket.\n\n**Toileting (18 months – 3 years).** If the Child is not yet using the toilet independently, caregivers in the 18 months – 3 years group provide diapering or toilet support. The Parent/Caregiver provides enough diapers or pull-ups, and wipes, for the day.\n\n**Please leave at home:** toys from home, electronics and any food containing nuts. Yalla is not responsible for personal items brought to camp."},{"id":"s16","type":"heading","text":"16. Non-discrimination"},{"id":"s16-body","type":"info","text":"At Yalla Coworking & Childcare, we are deeply committed to a welcoming, inclusive and respectful environment for every family. We embrace children and caregivers of every race, ethnicity, national origin, family structure, gender identity, sexual orientation, religion and background.\n\nWe do not tolerate discrimination of any kind within our community, and all families are expected to uphold these values. Discriminatory behavior, or conduct that undermines the inclusive nature of our program, may result in the end of camp participation under Section 6."},{"id":"s17","type":"heading","text":"17. Waiver"},{"id":"s17-body","type":"info","text":"No right under this agreement is waived (lost) merely by delaying or failing to exercise it. Consent to one act is not consent to any other or later act. Any waiver of a default under this agreement must be in writing and is not a waiver of any other default concerning the same or any other provision of this agreement."},{"id":"s18","type":"heading","text":"18. Good faith"},{"id":"s18-body","type":"info","text":"Yalla and the Parent/Caregiver each agree to act in good faith and with mutual respect for the duration of this agreement, including honesty and transparency about the Child’s care, health and well-being; timely communication of any concerns or changes; respectful interactions with everyone in the Yalla community; cooperation in addressing any issues in the best interest of the Child; and commitment to the terms of this agreement."},{"id":"s19","type":"heading","text":"19. Governing law"},{"id":"s19-body","type":"info","text":"This agreement is governed by the laws of the State of California, without regard to conflict-of-laws principles. Each party irrevocably consents to the exclusive personal jurisdiction and venue of the federal and state courts located in the County of San Diego, California, for any matter arising out of or relating to this agreement."},{"id":"s20","type":"heading","text":"20. Photographs"},{"id":"s20-body","type":"info","text":"Yalla may photograph camp activities. The Parent/Caregiver chooses separately, in the Photo & media preferences form in the Family Portal, whether to allow photos shared privately with participating families, and photos used publicly on Yalla’s website, social media or promotional materials. Taking part in camp never requires photo consent.\n\nBecause children share play spaces, the Child may occasionally appear in the background of a photo. That never overrides the Parent/Caregiver’s choices: before sharing, Yalla takes reasonable steps to leave out, crop or blur identifiable children whose families haven’t opted in to that use."},{"id":"sign","type":"heading","text":"Signatures"},{"id":"sign-body","type":"info","text":"**The undersigned have read and understand this agreement.**\n\nThis agreement and the [Yalla Family Handbook](/portal/handbook) (available in the Family Portal) set out all of Yalla’s obligations; there are no other implied obligations. Any changes to this agreement must be in writing and signed by both parties.\n\nYalla accepts this agreement on the date it is signed below. Accepted for Yalla Childcare LLC by Elizabeth Coburn, Managing Partner."},{"id":"read-understood","type":"agree","label":"I am the child’s parent or legal guardian and have read and agree to the Camp Yalla admission agreement for the camp days in this purchase.","required":true},{"id":"signature","type":"signature","label":"Parent/Caregiver signature"}]'::jsonb, 'fe271928bda6f3752aeecb103f638e80ca4d44aa8265742268894bcf7d91e096', true, 'Yalla')
ON CONFLICT ("id") DO NOTHING;
--> statement-breakpoint
